[
  {
    "day": 1,
    "title": "Arrival & Sigiriya Rural Adventure",
    "description": "Meet your chauffeur guide at Bandaranaike International Airport and begin your journey to Sigiriya. Experience authentic Sri Lankan village life through a traditional village tour featuring a bullock cart ride and a peaceful catamaran boat ride. Enjoy an authentic village lunch before relaxing in the beautiful surroundings of the Cultural Triangle."
  },
  {
    "day": 2,
    "title": "Travel to Kandy & Cultural Evening",
    "description": "Travel from Sigiriya to Kandy through the scenic landscapes of Matale. Visit a traditional spice garden to discover Sri Lanka's famous spices, herbs and Ayurvedic traditions. Continue to Kandy and enjoy an evening Kandyan cultural dance performance showcasing traditional music, dance and heritage."
  },
  {
    "day": 3,
    "title": "Full Day in Kandy: Lakeside Serenity",
    "description": "Spend a full day discovering the cultural heart of Sri Lanka. Visit the sacred Temple of the Tooth Relic, one of the country's most important Buddhist sites. Enjoy a relaxing walk around Kandy Lake, explore local markets and continue to the beautiful Royal Botanical Gardens of Peradeniya."
  },
  {
    "day": 4,
    "title": "The Road to Ella: Waterfalls & Tea Country",
    "description": "Leave Kandy and travel through Sri Lanka's spectacular central highlands toward Ella. Stop at the impressive Ramboda Falls and visit a tea plantation and working tea factory to learn about Sri Lanka's world-famous Ceylon tea. Continue through breathtaking mountain scenery before arriving in Ella and exploring the area around the iconic Nine Arches Bridge."
  },
  {
    "day": 5,
    "title": "Explore Ella at Your Own Pace",
    "description": "Enjoy a relaxed free day in Ella and choose how you would like to experience this beautiful mountain destination. Hike Little Adam's Peak, explore Ella Rock, visit Nine Arches Bridge, discover local cafes and viewpoints, or simply relax while enjoying the surrounding mountains and tea-covered landscapes."
  },
  {
    "day": 6,
    "title": "Yala Wilderness Stay: Into the Leopard's Lair",
    "description": "Travel from Ella toward Yala through changing landscapes and scenic countryside. Arrive at your safari accommodation near Yala National Park and check in. Spend the rest of the day relaxing and enjoying the natural surroundings, with the sounds of Sri Lanka's wilderness creating the perfect setting before your safari adventure."
  },
  {
    "day": 7,
    "title": "Yala Safari & Galle Coastal Heritage",
    "description": "Begin the day with an exciting safari adventure in Yala National Park, searching for Sri Lanka's iconic wildlife including leopards, elephants, sloth bears, crocodiles, deer, buffalo and diverse birdlife. After the safari, travel toward the southern coast and continue to historic Galle. Explore the UNESCO-listed Galle Fort, its colonial architecture, museums, galleries, boutique shops and atmospheric streets."
  },
  {
    "day": 8,
    "title": "Departure via the Southern Expressway",
    "description": "Enjoy your final breakfast before beginning your journey to Bandaranaike International Airport. Travel comfortably via Sri Lanka's Southern Expressway and arrive at the airport in time for your international departure, bringing your unforgettable 8-day Sri Lankan journey to an end."
  }
]

